import AppKit
import CryptoKit
import Foundation

@MainActor
final class ClipboardMonitor {
    private static let privateTypes: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.agilebits.onepassword.private"
    ]

    private let pasteboard: NSPasteboard
    private let settings: AppSettings
    private let sensitiveFilter: SensitiveContentFilter
    private var timer: Timer?
    private var lastChangeCount: Int
    private var handler: ((CapturedContent) -> Void)?

    init(
        pasteboard: NSPasteboard = .general,
        settings: AppSettings,
        sensitiveFilter: SensitiveContentFilter = SensitiveContentFilter()
    ) {
        self.pasteboard = pasteboard
        self.settings = settings
        self.sensitiveFilter = sensitiveFilter
        lastChangeCount = pasteboard.changeCount
    }

    func start(handler: @escaping (CapturedContent) -> Void) {
        self.handler = handler
        stop()
        lastChangeCount = pasteboard.changeCount
        let timer = Timer(timeInterval: 0.45, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.poll() }
        }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    func suppressCurrentChange() {
        lastChangeCount = pasteboard.changeCount
    }

    func poll() {
        guard pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount
        guard settings.isRecordingEnabled else { return }

        let frontmost = NSWorkspace.shared.frontmostApplication
        if let bundleID = frontmost?.bundleIdentifier,
           settings.excludedApplications.contains(bundleID) {
            return
        }
        let rawTypes = Set(pasteboard.types?.map(\.rawValue) ?? [])
        guard rawTypes.isDisjoint(with: Self.privateTypes) else { return }

        let sourceID = frontmost?.bundleIdentifier
        let sourceName = frontmost?.localizedName ?? "Unknown App"
        if let capture = capture(sourceID: sourceID, sourceName: sourceName) {
            handler?(capture)
        }
    }

    private func capture(sourceID: String?, sourceName: String) -> CapturedContent? {
        if let fileURLs = pasteboard.readObjects(
            forClasses: [NSURL.self],
            options: [.urlReadingFileURLsOnly: true]
        ) as? [URL], !fileURLs.isEmpty {
            let paths = fileURLs.map(\.path)
            guard let data = try? JSONEncoder().encode(paths) else { return nil }
            return makeCapture(
                type: .file,
                data: data,
                displayText: paths.joined(separator: "\n"),
                searchText: (paths.map { URL(fileURLWithPath: $0).lastPathComponent } + [sourceName]).joined(separator: " "),
                sourceID: sourceID,
                sourceName: sourceName
            )
        }

        if let imageData = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff),
           NSImage(data: imageData) != nil {
            return makeCapture(
                type: .image,
                data: imageData,
                displayText: nil,
                searchText: "image screenshot \(sourceName)",
                sourceID: sourceID,
                sourceName: sourceName
            )
        }

        if let string = pasteboard.string(forType: .string) {
            guard !sensitiveFilter.shouldIgnore(string) else { return nil }
            if let url = URL(string: string.trimmingCharacters(in: .whitespacesAndNewlines)),
               let scheme = url.scheme?.lowercased(),
               ["http", "https", "ftp", "mailto"].contains(scheme),
               let data = string.data(using: .utf8) {
                return makeCapture(
                    type: .url,
                    data: data,
                    displayText: string,
                    searchText: "\(string) \(url.host ?? "") \(sourceName)",
                    sourceID: sourceID,
                    sourceName: sourceName
                )
            }
        }

        if let rtf = pasteboard.data(forType: .rtf),
           let attributed = NSAttributedString(rtf: rtf, documentAttributes: nil),
           !attributed.string.isEmpty,
           !sensitiveFilter.shouldIgnore(attributed.string) {
            return makeCapture(
                type: .richText,
                data: rtf,
                displayText: attributed.string,
                searchText: "\(attributed.string) \(sourceName)",
                sourceID: sourceID,
                sourceName: sourceName
            )
        }

        if let html = pasteboard.data(forType: .html),
           let attributed = NSAttributedString(
                html: html,
                options: [.documentType: NSAttributedString.DocumentType.html],
                documentAttributes: nil
           ), !attributed.string.isEmpty,
           !sensitiveFilter.shouldIgnore(attributed.string) {
            return makeCapture(
                type: .html,
                data: html,
                displayText: attributed.string,
                searchText: "\(attributed.string) \(sourceName)",
                sourceID: sourceID,
                sourceName: sourceName
            )
        }

        if let string = pasteboard.string(forType: .string),
           !string.isEmpty,
           !sensitiveFilter.shouldIgnore(string),
           let data = string.data(using: .utf8) {
            return makeCapture(
                type: .text,
                data: data,
                displayText: string,
                searchText: "\(string) \(sourceName)",
                sourceID: sourceID,
                sourceName: sourceName
            )
        }
        return nil
    }

    private func makeCapture(
        type: ClipboardContentType,
        data: Data,
        displayText: String?,
        searchText: String,
        sourceID: String?,
        sourceName: String
    ) -> CapturedContent {
        var hasher = SHA256()
        hasher.update(data: Data(type.rawValue.utf8))
        hasher.update(data: data)
        let hash = hasher.finalize().map { String(format: "%02x", $0) }.joined()
        return CapturedContent(
            type: type,
            data: data,
            displayText: displayText,
            searchText: searchText,
            contentHash: hash,
            sourceAppIdentifier: sourceID,
            sourceAppName: sourceName
        )
    }
}
